<?php
require_once __DIR__ . '/../app/application.php';requirePermission('invoices.manage');$i=dbFetchOne('SELECT i.*,c.first_name,c.last_name,c.company_name,c.ice,c.tax_identifier,c.billing_address,a.name agency_name,a.address agency_address FROM invoices i JOIN customers c ON c.id=i.customer_id JOIN agencies a ON a.id=i.agency_id WHERE i.id=:id',['id'=>(int)($_GET['id']??0)]);if(!$i){http_response_code(404);exit('Invoice not found.');}requireAgencyAccess($i['agency_id']);$items=dbFetchAll('SELECT * FROM invoice_items WHERE invoice_id=:id ORDER BY sort_order,id',['id'=>$i['id']]);?><!doctype html><html><head><meta charset="utf-8"><title><?=e($i['invoice_number'])?></title><link rel="stylesheet" href="assets/app.css"><style>@media print{button{display:none}}</style></head><body><main class="page"><button class="btn secondary" onclick="print()">Print / Save PDF</button><div class="page-head"><div><h1>Invoice <?=e($i['invoice_number'])?></h1><p><?=e($i['agency_name'])?><br><?=e($i['agency_address'])?></p></div><div><?=statusBadge($i['status'])?><p><?=e($i['issued_at'])?></p></div></div><section class="card"><h2>Bill to</h2><p><?=e($i['company_name']?:$i['first_name'].' '.$i['last_name'])?></p><p>ICE: <?=e($i['ice'])?> · Tax ID: <?=e($i['tax_identifier'])?></p><p><?=e($i['billing_address'])?></p></section><div class="table-wrap"><table><tr><th>Description</th><th>Quantity</th><th>Unit price</th><th>Total</th></tr><?php foreach($items as $item):?><tr><td><?=e($item['description'])?></td><td><?=e($item['quantity'])?></td><td><?=money($item['unit_price'],$i['currency'])?></td><td><?=money($item['line_total'],$i['currency'])?></td></tr><?php endforeach;?><tr><th colspan="3">Tax</th><td><?=money($i['tax_amount'],$i['currency'])?></td></tr><tr><th colspan="3">Total</th><td><strong><?=money($i['total_amount'],$i['currency'])?></strong></td></tr><tr><th colspan="3">Paid</th><td><?=money($i['paid_amount'],$i['currency'])?></td></tr></table></div></main></body></html>

